 {PetBattle b;FillSecond(b);b.Pets[0]->States[BATTLEPET_STATE_Internal_InitialLevel]=1;b.Cast(0,290,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL);auto aura=SixthAura(b,0,289);std::cout<<"STOCKPILE "<<bool(aura)<<" max="<<b.Pets[0]->GetMaxHealth()<<" hp="<<b.Pets[0]->Health<<"\n";Require(aura&&b.Pets[0]->GetMaxHealth()==120,"Actual native Stockpile applies its twenty-percent health bonus");aura->Process(&b);Require(!aura->Expired,"Actual native reserve persists across rounds");b.Pets[0]->Health=60;b.Cast(0,290,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL);Require(aura->Expired&&b.Pets[0]->Health==80&&b.Pets[0]->GetMaxHealth()==100,"Actual native reserve removal then heal is symmetric");}
 {PetBattle b;FillSecond(b);b.Cast(0,303,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL);auto aura=SixthAura(b,0,302);Require(aura,"Actual native Plant aura exists");for(int i=0;i<3;++i)aura->Process(&b);Require(!aura->Expired&&b.Pets[0]->States[70]==3,"Actual native three-round Plant nutrient sequence");b.Pets[0]->Health=10;b.Cast(0,303,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL);Require(aura->Expired&&b.Pets[0]->Health==46&&b.Pets[0]->States[70]==0,"Actual Plant consumes three twelve-point nutrient rounds once");b.Cast(0,303,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL);aura=SixthAura(b,0,302);for(int i=0;i<12;++i)aura->Process(&b);Require(b.Pets[0]->States[70]==10,"Actual native Plant cannot accumulate beyond its ten-round cap");}
 for(uint32 ability:{325u,433u,439u,444u,465u,479u}){PetBattle b;FillSecond(b);b.Cast(0,ability,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL);Require(!b.PetAuras.empty(),"Actual native wall application");auto aura=b.PetAuras.back();aura->Process(&b);Require(!aura->Expired&&b.Pets[0]->States[BATTLEPET_STATE_Special_BlockedAttackCount]==2,"Actual native wall retains both charges across the round boundary");for(int i=0;i<2;++i)b.Cast(3,110,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL);Require(aura->Expired&&b.Pets[0]->Health==100,"Actual native two-charge wall blocks both incoming attacks then expires");b.Cast(3,110,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL);Require(b.Pets[0]->Health<100,"Actual spent wall does not block a third attack");}
 for(int state:{0,1,2}){PetBattle b;FillSecond(b);auto e=SecondEffect(b,419);Require(e.EffectInfo->Param[3]==BATTLEPET_STATE_Mechanic_IsStunned,"Matching native Takedown prerequisite");b.Pets[3]->States[BATTLEPET_STATE_Mechanic_IsStunned]=state;int expected=state?e.CalculateDamage(e.EffectInfo->Param[0]):0;e.HandleStateDamage();Require(b.Pets[3]->Health==100-expected,"Actual native conditional additional hit respects absent, present and stacked prerequisites");}
 for(uint32 row:{480u,620u,1130u,2366u}){int outcome=-1;for(int power:{0,2000}){PetBattle b;FillSecond(b);b.Pets[0]->States[BATTLEPET_STATE_Stat_Power]=power;auto e=SecondEffect(b,row);e.Target=3;e.HandleDamagePercent();if(outcome<0)outcome=b.Pets[3]->Health;else Require(b.Pets[3]->Health==outcome,"Actual native maximum-health percentages do not scale a second time with power");}}
 {PetBattle b;FillSecond(b);b.Pets[0]->Abilities[0]=665;b.Pets[0]->Cooldowns[0]=-1;b.Pets[0]->Health=10;b.Pets[0]->States[BATTLEPET_STATE_Stat_Power]=2000;Require(!b.CanCast(0,665),"Actual Consume Corpse admission rejects a living roster");b.Pets[1]->Health=0;b.Pets[1]->States[BATTLEPET_STATE_Is_Dead]=1;Require(b.CanCast(0,665),"Actual native corpse permits the ability");b.Cast(0,665,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL);Require(b.Pets[0]->Health==60&&b.Pets[1]->States[BATTLEPET_STATE_Special_ConsumedCorpse]==1&&!b.CanCast(0,665),"Actual full Consume Corpse selects one dead ally, heals its user by fifty percent and prevents reuse");b.Cast(0,665,1,PETBATTLE_ABILITY_TURN0_PROC_ON_NONE,PETBATTLE_CAST_TRIGGER_ALL);Require(b.Pets[0]->Health==60,"Repeated native corpse event cannot restore health again");}
 {PetBattle b;FillSecond(b);auto e=SecondEffect(b,1547);Require(e.EffectInfo->Param[1]==uint16(-10000)&&e.EffectInfo->Param[3]==10000,"Matching native Charge priority-removal row");b.Pets[0]->States[BATTLEPET_STATE_Stat_Speed]=11000;e.Target=0;e.HandleModState();Require(b.Pets[0]->States[BATTLEPET_STATE_Stat_Speed]==1000,"Actual native Charge removes its temporary priority across the bound");}
 for(uint32 row:{2253u,2546u}){int outcome=-1;for(int power:{0,2000}){PetBattle b;FillSecond(b);b.Pets[0]->States[BATTLEPET_STATE_Stat_Power]=power;b.Pets[0]->States[BATTLEPET_STATE_Last_HitTaken]=20;auto e=SecondEffect(b,row);e.Target=3;e.HandleDamagePercentTaken();if(outcome<0)outcome=b.Pets[3]->Health;else Require(b.Pets[3]->Health==outcome,"Actual Vengeance and Reflective Shield do not add caster power to the recorded hit");}}
 {PetBattleRequest request;request.OpponentGuid=player.GetGUID();Require(sPetBattleSystem->CanPlayerEnterInPetBattle(&player,&request)==PETBATTLE_REQUEST_TARGET_INVALID,"Actual native admission rejects a self duel before roster or geometry processing");}
 std::cout<<"PASS seventh10 actual native charged attacks,Stockpile,Plant,all six walls,conditional bonus hit,percentage damage,Consume Corpse once-only lifecycle,Charge recovery,damage feedback and self-duel admission;client traversal separate\n";
